episode_metadata.question:
What is the area, in square units, of triangle $ABC$? [asy]
unitsize(0.15inch);
path X = (-6.5, 0)--(5.5, 0);
path Y = (0, -3.5)--(0, 7.5);
draw(X); draw(Y);

for(int n=-6; n <= 5; ++n)
if( n != 0 )
draw( (n,0.25)--(n,-0.25) );
for(int n=-3; n <= 7; ++n)
if( n != 0 )
draw( (0.25,n)--(-0.25,n) );

pair A = (-4,3); pair B = (0,6); pair C = (2,-2);
dot(A); dot(B); dot(C);
label("$A\ (-4,3)$", A, NW); label("$B\ (0,6)$", B, NE); label("$C\ (2,-2)$", C, SE);
draw(A--B--C--cycle);
[/asy]

