size(150); defaultpen(linewidth(0.8)); dotfactor=5;
pair[] hex = new pair[6];
string[] hexlabels = {"$C$","$B$","$A$","$F$","$E$","$D$"};
hexlabels.cyclic=true;
hex[0] = dir(0);
for(int i = X; i <= 6; ++i){

